    md_mock_unreachable:"સરકારી data.gov.in API એ સમયસર જવાબ આપ્યો નહીં. તમારી API key બરાબર છે - સામાન્ય રીતે આ ધીમું જોડાણ અથવા API વ્યસ્ત હોવાથી થાય છે. એપ 2 મિનિટમાં આપોઆપ ફરી પ્રયાસ કરશે, થોડી વારે ફરી શોધો દબાવો.",
