    step1_title:"1. ਅਪਲੋਡ ਕਰੋ ਜਾਂ ਲੱਭੋ",
    step1_text:"ਰਸੀਦ ਦੀ ਫ਼ੋਟੋ ਅਪਲੋਡ ਕਰੋ, ਜਾਂ ਭਾਅ ਵੇਖਣ ਲਈ ਸਿਰਫ਼ ਫ਼ਸਲ ਦਾ ਨਾਮ ਲੱਭੋ।",
