    md_subtitle:"ਉਹ ਸਾਰੀਆਂ ਮੰਡੀਆਂ ਜੋ ਇਸ ਵੇਲੇ ਸਰਕਾਰ ਦੇ Agmarknet ਡਾਟਾਸੈੱਟ ਨੂੰ ਭਾਅ ਭੇਜ ਰਹੀਆਂ ਹਨ। ਕੋਈ ਇੱਕ ਖੋਜੋ, ਫਿਰ ਖੋਲ੍ਹ ਕੇ ਵੇਖੋ ਕਿ ਉੱਥੇ ਕਿਹੜੀਆਂ ਫ਼ਸਲਾਂ ਵਿਕਦੀਆਂ ਹਨ ਅਤੇ ਕੀ ਭਾਅ ਮਿਲ ਰਿਹਾ ਹੈ।",
