    md_mock_no_key:"ਬੈਕਐਂਡ ਦੀ .env ਫ਼ਾਈਲ ਵਿੱਚ ਕੋਈ MANDI_API_KEY ਨਹੀਂ ਹੈ। data.gov.in ਤੋਂ ਮੁਫ਼ਤ key ਲੈ ਕੇ ਬੈਕਐਂਡ ਦੁਬਾਰਾ ਚਾਲੂ ਕਰੋ।",
    md_mock_unreachable:"ਸਰਕਾਰੀ data.gov.in API ਨੇ ਸਮੇਂ ਸਿਰ ਜਵਾਬ ਨਹੀਂ ਦਿੱਤਾ। ਤੁਹਾਡੀ API key ਠੀਕ ਹੈ - ਆਮ ਤੌਰ ਤੇ ਇਹ ਹੌਲੀ ਕਨੈਕਸ਼ਨ ਜਾਂ API ਦੇ ਰੁੱਝੇ ਹੋਣ ਕਰਕੇ ਹੁੰਦਾ ਹੈ। ਐਪ 2 ਮਿੰਟਾਂ ਵਿੱਚ ਆਪੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੇਗੀ, ਥੋੜ੍ਹੀ ਦੇਰ ਬਾਅਦ ਫਿਰ ਖੋਜੋ ਦਬਾਓ।",
    md_mock_nothing:"ਸਰਕਾਰੀ API ਨੇ ਜਵਾਬ ਤਾਂ ਦਿੱਤਾ ਪਰ ਕੋਈ ਮੰਡੀ ਰਿਕਾਰਡ ਨਹੀਂ ਦਿੱਤਾ। ਮੰਡੀਆਂ ਦੇ ਰਿਪੋਰਟ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਦਿਨ ਦੇ ਸ਼ੁਰੂ ਵਿੱਚ ਇਹ ਹੋ ਸਕਦਾ ਹੈ। ਬਾਅਦ ਵਿੱਚ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
    md_mock_unexpected:"ਮੰਡੀ ਸੂਚੀ ਬਣਾਉਂਦੇ ਸਮੇਂ ਕੁਝ ਅਣਕਿਆਸਿਆ ਵਿਗੜ ਗਿਆ। ਗ਼ਲਤੀ ਵੇਖਣ ਲਈ ਬੈਕਐਂਡ ਟਰਮੀਨਲ ਜਾਂਚੋ।",
    md_mock_generic:"ਇਸ ਵੇਲੇ ਲਾਈਵ ਮੰਡੀ ਜਾਣਕਾਰੀ ਲੋਡ ਨਹੀਂ ਹੋ ਸਕੀ।",
