    mdet_mock_note:"ਸਰਕਾਰੀ API ਨੇ ਇਸ ਮੰਡੀ ਲਈ ਕੁਝ ਨਹੀਂ ਦਿੱਤਾ - ਹੇਠਾਂ ਸਿਰਫ਼ ਕਿਸਾਨਾਂ ਵੱਲੋਂ ਦੱਸੇ ਭਾਅ (ਜੇ ਹੋਣ) ਦਿਖ ਰਹੇ ਹਨ।",
    mdet_none_title:"ਅੱਜ ਇਸ ਮੰਡੀ ਲਈ ਕੋਈ ਫ਼ਸਲ ਦਰਜ ਨਹੀਂ ਹੋਈ।",
    mdet_none_text:"ਮੰਡੀਆਂ ਰੋਜ਼ ਰਿਪੋਰਟ ਨਹੀਂ ਦਿੰਦੀਆਂ। ਕੱਲ੍ਹ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ, ਜਾਂ ਕੋਈ ਹੋਰ ਮੰਡੀ ਚੁਣੋ।",
    mdet_footnote:"ਸਰਕਾਰੀ ਦਾ ਮਤਲਬ ਹੈ data.gov.in ਦੇ Agmarknet ਡਾਟਾਸੈੱਟ ਦਾ ਮਾਡਲ ਭਾਅ। ਸਾਡੇ ਕਿਸਾਨ ਦਾ ਮਤਲਬ ਹੈ ਇਸ ਐਪ ਨੂੰ ਵਰਤਣ ਵਾਲੇ ਕਿਸਾਨਾਂ ਨੇ ਇਸ ਮੰਡੀ ਵਿੱਚ ਜੋ ਭਾਅ ਦੱਸਿਆ ਉਸ ਦੀ ਔਸਤ। ਡੈਸ਼ ਦਾ ਮਤਲਬ ਹੈ ਉਸ ਸਰੋਤ ਕੋਲ ਉਸ ਫ਼ਸਲ ਦੀ ਜਾਣਕਾਰੀ ਨਹੀਂ ਹੈ।",
    nm_title:"ਤੁਹਾਡੇ ਨੇੜੇ ਸਭ ਤੋਂ ਵਧੀਆ ਭਾਅ ਦੇਣ ਵਾਲੀਆਂ ਮੰਡੀਆਂ",
    nm_subtitle:"ਆਪਣੇ ਆਲੇ-ਦੁਆਲੇ ਦੀਆਂ ਉਹ ਮੰਡੀਆਂ ਲੱਭੋ ਜੋ ਅੱਜ ਤੁਹਾਡੀ ਫ਼ਸਲ ਦਾ ਸਭ ਤੋਂ ਵੱਧ ਭਾਅ ਦੇ ਰਹੀਆਂ ਹਨ - ਤਾਂ ਜੋ ਪਤਾ ਲੱਗੇ ਕਿ ਕਿੱਥੇ ਜਾਣਾ ਫ਼ਾਇਦੇਮੰਦ ਹੈ।",
