    md_title:"মান্ডি তালিকা",
    md_subtitle:"যে সব মান্ডি এখন সরকারের Agmarknet তথ্যভাণ্ডারে দাম পাঠাচ্ছে। একটি খুঁজুন, তারপর খুলে দেখুন সেখানে কোন ফসল বিক্রি হয় আর কী দাম পাচ্ছে।",
