    md_err_load:"মান্ডির তালিকা লোড করা যায়নি। নিশ্চিত করুন যে ব্যাকএন্ড সার্ভার চালু আছে।",
    md_mock_title:"ছোট একটি নমুনা তালিকা দেখানো হচ্ছে, সরাসরি তথ্য নয়।",
    md_mock_no_key:"ব্যাকএন্ডের .env ফাইলে কোনো MANDI_API_KEY নেই। data.gov.in থেকে বিনামূল্যে key নিয়ে ব্যাকএন্ড আবার চালু করুন।",
    md_mock_unreachable:"সরকারি data.gov.in API সময়মতো সাড়া দেয়নি। আপনার API key ঠিক আছে - সাধারণত ধীর সংযোগ বা API ব্যস্ত থাকার কারণে এটি হয়। অ্যাপটি ২ মিনিটের মধ্যে নিজেই আবার চেষ্টা করবে, একটু পরে আবার খুঁজুন চাপুন।",
    md_mock_nothing:"সরকারি API সাড়া দিয়েছে কিন্তু কোনো মান্ডির রেকর্ড দেয়নি। মান্ডিগুলি রিপোর্ট দেওয়ার আগে দিনের শুরুতে এমন হতে পারে। পরে চেষ্টা করুন।",
    md_mock_unexpected:"মান্ডির তালিকা তৈরির সময় অপ্রত্যাশিত কিছু ভুল হয়েছে। ভুলটি দেখতে ব্যাকএন্ড টার্মিনাল দেখুন।",
    md_mock_generic:"এই মুহূর্তে সরাসরি মান্ডির তথ্য লোড করা যায়নি।",
    md_loading:"মান্ডিগুলি লোড হচ্ছে... সরকারি তথ্য আনতে প্রথমবার কয়েক সেকেন্ড লাগে।",
