    md_none_text:"প্রতিটি মান্ডি রোজ রিপোর্ট দেয় না, তাই আপনার চেনা মান্ডিটি আজকের তথ্যে না-ও থাকতে পারে। অন্য নাম দিয়ে দেখুন, বা সব {total}টি দেখতে রিসেট করুন।",
