    hero_subtitle:"நாங்கள் இரண்டு ஆதாரங்களிலிருந்து விலைகளை இணைக்கிறோம்: அரசு மண்டி விலைகள், மற்றும் இந்த செயலியைப் பயன்படுத்தும் மற்ற விவசாயிகளுக்கு உண்மையில் கிடைத்த விலை - அரசு எண்ணுடன் நேரடி ஆதாரமும் தெரியும்.",
