    testimonial_1_text:"வெங்காயத்திற்கு அரசு விலையை விட 15% குறைவாகக் கிடைத்தது தெரிந்தது. அடுத்த முறை வேறு மண்டியைத் தேர்ந்தெடுத்து அதிகம் சம்பாதித்தேன்.",
    testimonial_1_name:"ரமேஷ் பாட்டீல்",
    testimonial_1_role:"வெங்காய விவசாயி, நாசிக்",
    testimonial_2_text:"பயன்படுத்த மிகவும் எளிது. ரசீதின் புகைப்படத்தை எடுத்தால் போதும், விலை நியாயமானதா என்று சொல்லிவிடும். என் தந்தையும் இதைப் பயன்படுத்துகிறார்.",
