    testimonial_2_role:"பருத்தி விவசாயி, ஜல்காவ்",
    testimonial_3_text:"கோதுமையை விற்கும் முன் இந்த வாரம் எந்த மண்டி நல்ல விலை தருகிறது என்று செயலியில் பார்ப்பேன். இது எனக்கு உண்மையான பணத்தைச் சேமித்துள்ளது.",
