    md_err_load:"மண்டி பட்டியலை ஏற்ற முடியவில்லை. பின்தள சேவையகம் இயங்குகிறதா எனப் பாருங்கள்.",
    md_mock_title:"சிறிய மாதிரிப் பட்டியல் காட்டப்படுகிறது, நேரடித் தரவு அல்ல.",
    md_mock_no_key:"பின்தளத்தின் .env கோப்பில் MANDI_API_KEY இல்லை. data.gov.in இலிருந்து இலவச key பெற்று பின்தளத்தை மீண்டும் தொடங்குங்கள்.",
    md_mock_unreachable:"அரசு data.gov.in API சரியான நேரத்தில் பதிலளிக்கவில்லை. உங்கள் API key சரியாக உள்ளது - பொதுவாக இது மெதுவான இணைப்பு அல்லது API பிஸியாக இருப்பதால் நிகழ்கிறது. செயலி 2 நிமிடங்களில் தானாக மீண்டும் முயலும், சிறிது நேரம் கழித்து மீண்டும் தேடு அழுத்துங்கள்.",
    md_mock_nothing:"அரசு API பதிலளித்தது ஆனால் எந்த மண்டிப் பதிவும் தரவில்லை. மண்டிகள் தெரிவிப்பதற்கு முன் நாளின் தொடக்கத்தில் இது நிகழலாம். பிறகு முயலுங்கள்.",
    md_mock_unexpected:"மண்டி பட்டியலை உருவாக்கும்போது எதிர்பாராத பிழை ஏற்பட்டது. பிழையைப் பார்க்க பின்தள டெர்மினலைப் பாருங்கள்.",
    md_mock_generic:"தற்போது நேரடி மண்டித் தரவை ஏற்ற முடியவில்லை.",
    md_loading:"மண்டிகள் ஏற்றப்படுகின்றன... அரசுத் தரவைக் கொண்டுவர முதல் முறை சில வினாடிகள் ஆகும்.",
    md_none_title:"உங்கள் தேடலுக்கு எந்த மண்டியும் பொருந்தவில்லை.",
    md_none_text:"ஒவ்வொரு மண்டியும் தினமும் தெரிவிப்பதில்லை, எனவே உங்களுக்குத் தெரிந்த மண்டி இன்றைய தரவில் இல்லாமல் இருக்கலாம். வேறு பெயரை முயலுங்கள், அல்லது அனைத்து {total} ஐயும் பார்க்க மீட்டமைக்கவும்.",
