    mdet_mock_note:"அரசு API இந்த மண்டிக்கு எதுவும் தரவில்லை - கீழே விவசாயிகள் தெரிவித்த விலைகள் மட்டுமே (இருந்தால்) காட்டப்படுகின்றன.",
    mdet_none_title:"இன்று இந்த மண்டிக்கு எந்தப் பயிரும் தெரிவிக்கப்படவில்லை.",
    mdet_none_text:"மண்டிகள் தினமும் தெரிவிப்பதில்லை. நாளை மீண்டும் முயலுங்கள், அல்லது வேறு மண்டியைத் தேர்ந்தெடுங்கள்.",
    mdet_footnote:"அரசு என்பது data.gov.in இன் Agmarknet தரவுத்தொகுப்பின் மோடல் விலை. நமது விவசாயிகள் என்பது இந்தச் செயலியைப் பயன்படுத்தும் விவசாயிகள் இந்த மண்டியில் பெற்றதாகத் தெரிவித்த விலையின் சராசரி. கோடு என்றால் அந்த ஆதாரத்தில் அந்தப் பயிருக்குத் தரவு இல்லை.",
    nm_title:"உங்களுக்கு அருகில் அதிக விலை தரும் மண்டிகள்",
    nm_subtitle:"உங்கள் சுற்றுவட்டாரத்தில் இன்று உங்கள் பயிருக்கு அதிக விலை தரும் மண்டிகளைக் கண்டறியுங்கள் - எங்கு செல்வது லாபகரம் எனத் தெரியும்.",
    nm_placeholder_crop:"எ.கா. வெங்காயம், கோதுமை, தக்காளி",
    nm_search_within:"இந்த தூரத்திற்குள் தேடு",
    nm_your_location:"உங்கள் இருப்பிடம்",
    nm_finding_you:"உங்களைக் கண்டறிகிறோம்...",
    nm_using_location:"உங்கள் இருப்பிடம் பயன்படுத்தப்படுகிறது",
    nm_use_my_location:"என் இருப்பிடத்தைப் பயன்படுத்து",
    nm_place_placeholder:"உங்கள் ஊர் அல்லது மாவட்டத்தை எழுதுங்கள், எ.கா. நாசிக்",
    nm_find_btn:"சிறந்த மண்டிகளைக் கண்டறி",
    nm_err_no_geolocation:"இந்த உலாவி உங்கள் இருப்பிடத்தைப் பகிர முடியாது. தயவுசெய்து உங்கள் ஊரின் பெயரை எழுதுங்கள்.",
    nm_err_denied:"நீங்கள் இருப்பிட அனுமதி தரவில்லை. தயவுசெய்து கீழே உங்கள் ஊரின் பெயரை எழுதுங்கள்.",
    nm_err_unavailable:"உங்கள் இருப்பிடம் இப்போது கிடைக்கவில்லை. தயவுசெய்து கீழே உங்கள் ஊரின் பெயரை எழுதுங்கள்.",
    nm_err_timeout:"உங்கள் இருப்பிடத்தைக் கண்டறிய அதிக நேரம் ஆனது. தயவுசெய்து கீழே உங்கள் ஊரின் பெயரை எழுதுங்கள்.",
    nm_err_generic_location:"உங்கள் இருப்பிடத்தைப் பெற முடியவில்லை.",
    nm_err_need_crop:"தயவுசெய்து பயிரின் பெயரை உள்ளிடுங்கள், எ.கா. வெங்காயம்.",
    nm_err_need_place:"என் இருப்பிடத்தைப் பயன்படுத்து என்பதை அழுத்துங்கள், அல்லது எந்த ஊருக்கு அருகில் விற்கிறீர்கள் எனத் தட்டச்சு செய்யுங்கள்.",
    nm_err_search:"அருகிலுள்ள மண்டிகளைத் தேட முடியவில்லை. பின்தளம் இயங்குகிறதா?",
    nm_none_title:"{radius} கிமீ சுற்றளவில் எந்த மண்டியும் இன்று இந்தப் பயிரைத் தெரிவிக்கவில்லை.",
    nm_none_outside:"{count} மண்டிகளில் இதற்கு விலை உள்ளது, ஆனால் அவை அனைத்தும் {radius} கிமீக்கு அப்பால் உள்ளன. பரந்த சுற்றளவில் தேடுங்கள்.",
    nm_none_text:"ஒவ்வொரு மண்டியும் ஒவ்வொரு பயிரையும் தினமும் தெரிவிப்பதில்லை. நாளை மீண்டும் முயலுங்கள், அல்லது வேறு பயிரைப் பாருங்கள்.",
    nm_best_price_near:"உங்களுக்கு அருகில் சிறந்த விலை",
    nm_closest_to_you:"உங்களுக்கு மிக அருகில்",
    nm_tradeoff:"அதிக விலை தரும் மண்டி ஒரு குவிண்டாலுக்கு ₹{extra} அதிகம் தருகிறது, ஆனால் அது மிக அருகிலுள்ள மண்டியை விட {km} கிமீ தூரம். 10 குவிண்டாலுக்கு அது ₹{total} அதிகம் - உங்கள் போக்குவரத்துச் செலவுடன் ஒப்பிட்டுப் பாருங்கள்.",
