    nm_same_district:"அதே மாவட்டம்",
    nm_rough_estimate:"தோராயமானது",
    nm_km_away:"{km} கிமீ தூரம்",
    nm_km_away_rough:"~{km} கிமீ தூரம் (தோராயம்)",
    nm_in_your_area_lower:"உங்கள் பகுதியில்",
    nm_footnote:"தூரங்கள் நேர்கோட்டில் அளக்கப்பட்டவை, சாலைத் தூரம் அல்ல - உண்மையான பயணம் நீளமாக இருக்கும். ஒவ்வொரு மண்டியின் மாவட்ட மையம் வரை அளக்கப்பட்டுள்ளது, எனவே உங்கள் சொந்த மாவட்டத்தின் மண்டிகள் துல்லியமான எண்ணுக்குப் பதிலாக உங்கள் பகுதியில் எனக் காட்டப்படுகின்றன.",
    nm_footnote_unlocated:"{count} மண்டிகளுக்கு விலை இருந்தது ஆனால் வரைபடத்தில் அவற்றின் இடம் கிடைக்கவில்லை, எனவே அவை பட்டியலில் இல்லை.",
    nm_footnote_mock:"மாதிரி விலைகள் காட்டப்படுகின்றன - நேரடி அரசுத் தரவு கிடைக்கவில்லை.",
