    mdet_charts_title:"வகை வாரியாக பயிர் விலைகள்",
    mdet_charts_note:"ஒவ்வொரு விளக்கப்படத்திலும் ஒரு பயிர் வகை, பக்கத்தில் ஒரு குவிண்டாலுக்கான விலை. வகைகளாகப் பிரித்திருப்பதற்குக் காரணம்: குவிண்டாலுக்கு ₹2,00,000 மசாலாவும் ₹800 காய்கறியும் ஒரே விளக்கப்படத்தில் இருந்தால் மற்ற அனைத்துக் கம்பிகளும் தட்டையாகத் தெரியும்.",
    mdet_chart_crop_count:"{count} பயிர்கள்",
    md_charts_title:"இன்று என்ன வியாபாரம் ஆகிறது",
    md_charts_note:"இன்று தெரிவித்த {mandis} மண்டிகள் மற்றும் {crops} பயிர்களில் இருந்து. ஒவ்வொரு கம்பியும் அந்தப் பயிருக்கு எத்தனை மண்டிகள் விலை தெரிவித்தன என்பதைக் காட்டுகிறது - இது வரத்து அளவு அல்ல. அரசு சேவை விலைகளை மட்டுமே வெளியிடுகிறது, அதில் அளவு பற்றிய எந்தத் தகவலும் இல்லை.",
