    md_title:"మండి జాబితా",
    md_subtitle:"ప్రస్తుతం ప్రభుత్వ Agmarknet డేటాసెట్‌కు ధరలు పంపుతున్న అన్ని మండీలు. ఒకదాన్ని వెతికి, తెరిచి అక్కడ ఏ పంటలు అమ్ముతున్నారో, ఏ ధర వస్తోందో చూడండి.",
