    md_mock_title:"చిన్న నమూనా జాబితా చూపుతున్నాం, ప్రత్యక్ష సమాచారం కాదు.",
    md_mock_no_key:"బ్యాకెండ్ .env ఫైల్‌లో MANDI_API_KEY లేదు. data.gov.in నుండి ఉచిత key తీసుకుని బ్యాకెండ్ మళ్లీ ప్రారంభించండి.",
    md_mock_unreachable:"ప్రభుత్వ data.gov.in API సమయానికి స్పందించలేదు. మీ API key సరిగ్గానే ఉంది - సాధారణంగా ఇది నెమ్మది కనెక్షన్ లేదా API బిజీగా ఉండటం వల్ల జరుగుతుంది. యాప్ 2 నిమిషాల్లో తనంతట తానే మళ్లీ ప్రయత్నిస్తుంది, కొద్దిసేపటి తర్వాత మళ్లీ వెతకండి నొక్కండి.",
    md_mock_nothing:"ప్రభుత్వ API స్పందించింది కానీ ఏ మండి రికార్డూ ఇవ్వలేదు. మండీలు నివేదించే ముందు రోజు మొదట్లో ఇలా జరగవచ్చు. తర్వాత ప్రయత్నించండి.",
    md_mock_unexpected:"మండి జాబితా తయారు చేస్తున్నప్పుడు ఊహించని తప్పు జరిగింది. తప్పు చూడటానికి బ్యాకెండ్ టెర్మినల్ చూడండి.",
    md_mock_generic:"ప్రస్తుతం ప్రత్యక్ష మండి సమాచారం లోడ్ కాలేదు.",
