    mdet_footnote:"ప్రభుత్వం అంటే data.gov.in Agmarknet డేటాసెట్ లోని మోడల్ ధర. మన రైతులు అంటే ఈ యాప్ వాడే రైతులు ఈ మండీలో పొందామని చెప్పిన ధరల సగటు. డాష్ అంటే ఆ మూలం వద్ద ఆ పంట సమాచారం లేదు.",
