    testimonial_2_text:"ಬಳಸಲು ತುಂಬಾ ಸುಲಭ. ನಾನು ರಸೀದಿಯ ಫೋಟೋ ತೆಗೆದರೆ ಸಾಕು, ಬೆಲೆ ನ್ಯಾಯಯುತವಾಗಿತ್ತೇ ಎಂದು ಹೇಳುತ್ತದೆ. ನನ್ನ ತಂದೆಯೂ ಇದನ್ನು ಬಳಸುತ್ತಾರೆ.",
