    md_mock_no_key:"ബാക്കെൻഡിന്റെ .env ഫയലിൽ MANDI_API_KEY ഇല്ല. data.gov.in ൽ നിന്ന് സൗജന്യ key എടുത്ത് ബാക്കെൻഡ് വീണ്ടും തുടങ്ങുക.",
    md_mock_unreachable:"സർക്കാർ data.gov.in API സമയത്ത് മറുപടി നൽകിയില്ല. നിങ്ങളുടെ API key ശരിയാണ് - സാധാരണയായി ഇത് വേഗത കുറഞ്ഞ കണക്ഷൻ അല്ലെങ്കിൽ API തിരക്കിലായതുകൊണ്ടാണ്. ആപ്പ് 2 മിനിറ്റിനുള്ളിൽ സ്വയം വീണ്ടും ശ്രമിക്കും, കുറച്ച് കഴിഞ്ഞ് വീണ്ടും തിരയുക അമർത്തുക.",
    md_mock_nothing:"സർക്കാർ API മറുപടി നൽകി പക്ഷേ ഒരു മണ്ടി രേഖയും തന്നില്ല. മണ്ടികൾ അറിയിക്കുന്നതിന് മുമ്പ് ദിവസത്തിന്റെ തുടക്കത്തിൽ ഇത് സംഭവിക്കാം. പിന്നീട് ശ്രമിക്കുക.",
    md_mock_unexpected:"മണ്ടി പട്ടിക ഉണ്ടാക്കുമ്പോൾ അപ്രതീക്ഷിതമായ പിഴവ് സംഭവിച്ചു. പിഴവ് കാണാൻ ബാക്കെൻഡ് ടെർമിനൽ നോക്കുക.",
