    md_none_text:"എല്ലാ മണ്ടിയും എന്നും അറിയിക്കാറില്ല, അതിനാൽ നിങ്ങൾക്കറിയാവുന്ന മണ്ടി ഇന്നത്തെ വിവരത്തിൽ ഇല്ലായിരിക്കാം. മറ്റൊരു പേര് പരീക്ഷിക്കുക, അല്ലെങ്കിൽ എല്ലാ {total} എണ്ണവും കാണാൻ പുനഃസജ്ജമാക്കുക.",
