    mdet_footnote:"സർക്കാർ എന്നാൽ data.gov.in ന്റെ Agmarknet ഡാറ്റാസെറ്റിലെ മോഡൽ വില. നമ്മുടെ കർഷകർ എന്നാൽ ഈ ആപ്പ് ഉപയോഗിക്കുന്ന കർഷകർക്ക് ഈ മണ്ടിയിൽ കിട്ടിയെന്ന് അറിയിച്ച വിലയുടെ ശരാശരി. ഡാഷ് എന്നാൽ ആ ഉറവിടത്തിൽ ആ വിളയുടെ വിവരമില്ല എന്നാണ്.",
