    testimonial_2_text:"ବ୍ୟବହାର କରିବା ବହୁତ ସହଜ। ମୁଁ କେବଳ ରସିଦର ଫଟୋ ଉଠାଏ ଏବଂ ଏହା କହିଦିଏ ଦାମ ଉଚିତ ଥିଲା କି ନାହିଁ। ମୋ ବାପା ମଧ୍ୟ ଏହା ବ୍ୟବହାର କରନ୍ତି।",
