    testimonial_3_text:"ଗହମ ବିକ୍ରି କରିବା ପୂର୍ବରୁ ମୁଁ ଆପରେ ଦେଖେ ଏହି ସପ୍ତାହରେ କେଉଁ ମଣ୍ଡି ଭଲ ଦାମ ଦେଉଛି। ଏଥିରେ ମୋର ପ୍ରକୃତ ଟଙ୍କା ବଞ୍ଚିଛି।",
