    md_title:"ମଣ୍ଡି ତାଲିକା",
    md_subtitle:"ବର୍ତ୍ତମାନ ସରକାରଙ୍କ Agmarknet ତଥ୍ୟଭଣ୍ଡାରକୁ ଦର ପଠାଉଥିବା ସମସ୍ତ ମଣ୍ଡି। ଗୋଟିଏ ଖୋଜନ୍ତୁ, ତାପରେ ଖୋଲି ଦେଖନ୍ତୁ ସେଠାରେ କେଉଁ ଫସଲ ବିକ୍ରି ହୁଏ ଏବଂ କଣ ଦର ମିଳୁଛି।",
