    md_err_load:"ମଣ୍ଡି ତାଲିକା ଲୋଡ୍ ହେଲା ନାହିଁ। ବ୍ୟାକଏଣ୍ଡ ସର୍ଭର ଚାଲୁଛି କି ନାହିଁ ଦେଖନ୍ତୁ।",
    md_mock_title:"ଛୋଟ ନମୁନା ତାଲିକା ଦେଖାଯାଉଛି, ସିଧା ତଥ୍ୟ ନୁହେଁ।",
    md_mock_no_key:"ବ୍ୟାକଏଣ୍ଡର .env ଫାଇଲରେ MANDI_API_KEY ନାହିଁ। data.gov.in ରୁ ମାଗଣା key ନେଇ ବ୍ୟାକଏଣ୍ଡ ପୁଣି ଆରମ୍ଭ କରନ୍ତୁ।",
    md_mock_unreachable:"ସରକାରୀ data.gov.in API ସମୟରେ ଉତ୍ତର ଦେଲା ନାହିଁ। ଆପଣଙ୍କ API key ଠିକ୍ ଅଛି - ସାଧାରଣତଃ ଏହା ମନ୍ଥର ସଂଯୋଗ କିମ୍ବା API ବ୍ୟସ୍ତ ଥିବାରୁ ହୁଏ। ଆପ୍ 2 ମିନିଟ୍ ମଧ୍ୟରେ ନିଜେ ପୁଣି ଚେଷ୍ଟା କରିବ, କିଛି ସମୟ ପରେ ପୁଣି ଖୋଜନ୍ତୁ ଦବାନ୍ତୁ।",
    md_mock_nothing:"ସରକାରୀ API ଉତ୍ତର ଦେଲା କିନ୍ତୁ କୌଣସି ମଣ୍ଡି ରେକର୍ଡ ଦେଲା ନାହିଁ। ମଣ୍ଡିମାନେ ଜଣାଇବା ପୂର୍ବରୁ ଦିନର ଆରମ୍ଭରେ ଏପରି ହୋଇପାରେ। ପରେ ଚେଷ୍ଟା କରନ୍ତୁ।",
    md_mock_unexpected:"ମଣ୍ଡି ତାଲିକା ତିଆରି କରିବା ସମୟରେ ଅପ୍ରତ୍ୟାଶିତ ତ୍ରୁଟି ଘଟିଲା। ତ୍ରୁଟି ଦେଖିବାକୁ ବ୍ୟାକଏଣ୍ଡ ଟର୍ମିନାଲ ଦେଖନ୍ତୁ।",
    md_mock_generic:"ବର୍ତ୍ତମାନ ସିଧା ମଣ୍ଡି ତଥ୍ୟ ଲୋଡ୍ ହୋଇପାରିଲା ନାହିଁ।",
    md_loading:"ମଣ୍ଡିଗୁଡ଼ିକ ଲୋଡ୍ ହେଉଛି... ସରକାରୀ ତଥ୍ୟ ଆଣିବାକୁ ପ୍ରଥମ ଥର କିଛି ସେକେଣ୍ଡ ଲାଗେ।",
    md_none_title:"ଆପଣଙ୍କ ଖୋଜ ସହିତ କୌଣସି ମଣ୍ଡି ମେଳ ଖାଇଲା ନାହିଁ।",
    md_none_text:"ପ୍ରତ୍ୟେକ ମଣ୍ଡି ପ୍ରତିଦିନ ଜଣାନ୍ତି ନାହିଁ, ତେଣୁ ଆପଣ ଜାଣିଥିବା ମଣ୍ଡି ଆଜିର ତଥ୍ୟରେ ନଥାଇପାରେ। ଅନ୍ୟ ନାମ ଚେଷ୍ଟା କରନ୍ତୁ, କିମ୍ବା ସବୁ {total}ଟି ଦେଖିବାକୁ ରିସେଟ୍ କରନ୍ତୁ।",
